{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "icon",
      "type": "IconType",
      "description": "Icon to display before the label. See `astryx docs icons` for valid semantic names."
    },
    {
      "name": "label",
      "type": "ReactNode",
      "description": "Primary label text.",
      "required": true
    },
    {
      "name": "description",
      "type": "ReactNode",
      "description": "Secondary description text displayed below the label."
    },
    {
      "name": "onClick",
      "type": "(event: MouseEvent) => void",
      "description": "Callback when the item is selected. A keyboard activation arrives as a synthesized click carrying the key's modifiers. On a row with `href` it runs before the browser navigates and is skipped for a modified click (⌘, Ctrl, Shift, Alt, middle button), which is left to the browser."
    },
    {
      "name": "href",
      "type": "string",
      "description": "Address the row navigates to. The row then renders as a real anchor with role=\"menuitem\" (through LinkProvider), so a modified click or a middle click keeps the browser's meaning — a new tab — instead of running onClick."
    },
    {
      "name": "target",
      "type": "'_blank' | '_self'",
      "description": "Link target. Only used with href."
    },
    {
      "name": "rel",
      "type": "string",
      "description": "Link relationship. noopener noreferrer is added for target=\"_blank\". Only used with href."
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Whether the row is unavailable. Disabled rows expose aria-disabled, remove link destinations, and suppress activation.",
      "default": "false"
    },
    {
      "name": "endContent",
      "type": "ReactNode",
      "description": "Non-interactive content rendered after the label and description."
    },
    {
      "name": "hasCloseOnSelect",
      "type": "boolean",
      "description": "Whether activating the item closes the menu. Set false for an action that reports its result on the item itself.",
      "default": "true"
    },
    {
      "name": "variant",
      "type": "'default' | 'destructive'",
      "description": "Visual variant. 'destructive' renders the label, description, and icon in the error color for dangerous actions (e.g. Delete).",
      "default": "'default'"
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value: not an inline style object like style={{}}."
    },
    {
      "name": "ref",
      "type": "React.Ref<HTMLElement>",
      "description": "Ref forwarded to the row root, the element carrying role=\"menuitem\". Register the row with an element-keyed observer or overlay."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
